        var buf = new byte[total];
        Array.Copy(msg, buf, len);
        buf[len] = 0x80;
        BinaryPrimitives.WriteUInt32LittleEndian(buf.AsSpan(total - 8), unchecked((uint)bitLen));
        BinaryPrimitives.WriteUInt32LittleEndian(buf.AsSpan(total - 4), (uint)(bitLen >> 32));
        uint a0 = 0x67452301u, b0 = 0xEFCDAB89u, c0 = 0x98BADCFEu, d0 = 0x10325476u;
        for (int off = 0; off < total; off += 64)
        {
