            {
                int o = off + i * 4;
                M[i] = (uint)(buf[o] | (buf[o + 1] << 8) | (buf[o + 2] << 16) | (buf[o + 3] << 24));
            }
            uint A = a0, B = b0, C = c0, D = d0;
            for (int i = 0; i < 64; i++)
            {
                uint F; int g;
                if (i < 16) { F = (B & C) | (~B & D); g = i; }
                else if (i < 32) { F = (D & B) | (~D & C); g = (5 * i + 1) & 15; }
                else if (i < 48) { F = B ^ C ^ D; g = (3 * i + 5) & 15; }
                else { F = C ^ (B | ~D); g = (7 * i) & 15; }
                F = F + A + MK[i] + M[g];
                A = D; D = C; C = B;
                B = B + Rotl(F, MS[i]);
            }
            a0 += A; b0 += B; c0 += C; d0 += D;
        }
        var o2 = new byte[16];
        BinaryPrimitives.WriteUInt32LittleEndian(o2.AsSpan(0), a0);
        BinaryPrimitives.WriteUInt32LittleEndian(o2.AsSpan(4), b0);
        BinaryPrimitives.WriteUInt32LittleEndian(o2.AsSpan(8), c0);
        BinaryPrimitives.WriteUInt32LittleEndian(o2.AsSpan(12), d0);
        return o2;
    }

