    public static byte[] HexToBytes(string h)
    {
        if ((h.Length & 1) != 0) h = "0" + h;
        var o = new byte[h.Length >> 1];
        for (int i = 0; i < o.Length; i++) o[i] = byte.Parse(h.Substring(i * 2, 2), System.Globalization.NumberStyles.HexNumber);
        return o;
    }

