internal static class S8x
{
    static void LogInfo(string msg)
    {
        Console.ForegroundColor = ConsoleColor.Green;
        Console.Write("[INFO] ");
        Console.ResetColor();
        Console.WriteLine(msg);
    }

    static void LogWarn(string msg)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.Write("[WARN] ");
        Console.ResetColor();
        Console.WriteLine(msg);
    }

    static void LogError(string msg)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.Write("[ERROR] ");
        Console.ResetColor();
        Console.WriteLine(msg);
    }

    static AppConfig LoadOrCreateConfig()
    {
        string baseDir = AppContext.BaseDirectory;
        string cfgFile = Path.Combine(baseDir, "appsettings.json");
        if (!File.Exists(cfgFile) && File.Exists("appsettings.json"))
        {
            cfgFile = Path.GetFullPath("appsettings.json");
        }

        if (!File.Exists(cfgFile))
        {
            var def = new AppConfig();
            var options = new JsonSerializerOptions { WriteIndented = true };
            string json = JsonSerializer.Serialize(def, options);
            File.WriteAllText(cfgFile, json, Encoding.UTF8);

            Console.WriteLine("appsettings.json not found. A default configuration file has been created.");
            Console.WriteLine("Please edit appsettings.json and press any key to continue...");
            if (!Console.IsInputRedirected)
            {
                try { Console.ReadKey(true); } catch { }
            }
        }

        try
        {
            string content = File.ReadAllText(cfgFile, Encoding.UTF8);
            var parsed = JsonSerializer.Deserialize<AppConfig>(content, new JsonSerializerOptions 
            { 
                PropertyNameCaseInsensitive = true,
                TypeInfoResolver = new System.Text.Json.Serialization.Metadata.DefaultJsonTypeInfoResolver()
            });
            if (parsed != null) return parsed;
        }
        catch (Exception ex)
        {
            LogError($"Failed to load configuration file: {ex.Message}. Using default settings.");
        }
        return new AppConfig();
    }
    static readonly uint Gate = CalcGate();

    static uint CalcGate()
    {
        uint x = 0x9E3779B9u;
        for (int i = 0; i < 64; i++)
        {
            x ^= x << 13;
            x ^= x >> 17;
            x ^= x << 5;
        }
        return x;
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool CheckRemoteDebuggerPresent(IntPtr hProcess, ref bool isDebuggerPresent);

    [DllImport("ntdll.dll")]
    static extern int NtQueryInformationProcess(IntPtr processHandle, int processInformationClass, ref IntPtr processInformation, int processInformationLength, out int returnLength);

    static readonly string[] BadNames =
    {
        "dnspy", "dnspy-x", "x64dbg", "x32dbg", "x96dbg", "ida", "ida64", "ida32", "ollydbg",
        "de4dot", "ilspy", "ilspycmd", "processhacker", "systemexplorer", "cheatengine",
        "megadumper", "dotpeek", "justdecompile", "reflector",
    };

    static bool ProcNameBad(string name)
    {
        if (string.IsNullOrEmpty(name)) return false;
        name = name.ToLowerInvariant();
        foreach (var b in BadNames)
            if (name == b || name.StartsWith(b + ".", StringComparison.Ordinal) || name.StartsWith(b + " ", StringComparison.Ordinal)) return true;
        return false;
    }

    static long _procScan = 0;
    static bool _procBad;

    static bool NativeDbg()
    {
        if (!OperatingSystem.IsWindows()) return false;
        try
        {
            bool remote = false;
            CheckRemoteDebuggerPresent(Process.GetCurrentProcess().Handle, ref remote);
            if (remote) return true;
            IntPtr port = IntPtr.Zero;
            int rl;
            if (NtQueryInformationProcess(Process.GetCurrentProcess().Handle, 7, ref port, IntPtr.Size, out rl) == 0 && port != IntPtr.Zero)
                return true;
        }
        catch { }
        return false;
    }

    static bool HostileProcess()
    {
        long now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        if (now - _procScan > 20)
        {
            _procScan = now;
            _procBad = false;
            try
            {
                foreach (var p in Process.GetProcesses())
                {
                    try { if (ProcNameBad(p.ProcessName)) { _procBad = true; break; } }
                    catch { }
                }
            }
            catch { }
        }
        return _procBad;
    }

    static bool HostileParent()
    {
        try
        {
            var par = ParentUtilities.ParentOf(Process.GetCurrentProcess().Id);
            if (par != null && ProcNameBad(par)) return true;
        }
        catch { }
        return false;
    }

    static bool SlowTick()
    {
        try
        {
            var sw = Stopwatch.StartNew();
            ulong acc = 0;
            for (int i = 0; i < 400000; i++)
            {
                acc = acc * 1664525u + 1013904223u;
                acc ^= acc >> 13;
            }
            sw.Stop();
            if (acc == 0xDEADBEEFDEADBEEFul) return false;
            return sw.ElapsedMilliseconds > 5000;
        }
        catch { return true; }
    }

    static bool Guard(bool full)
    {
        bool bad;
        try
        {
            if (Debugger.IsAttached) bad = true;
            else if (Debugger.IsLogging()) bad = true;
            else if (NativeDbg()) bad = true;
            else if (SlowTick()) bad = true;
            else if (full && HostileProcess()) bad = true;
            else if (full && HostileParent()) bad = true;
            else bad = false;
        }
        catch { bad = true; }
        return bad;
    }

    static void Drop()
    {
        Environment.Exit(0);
    }

    static byte[] VerifyBlobs()
    {
        var b27 = G7.Blob27();
        var b41 = G7.Blob41();
        var h1 = G7.Sha256B64(b27);
        var h2 = G7.Sha256B64(b41);
        var v1 = Encoding.UTF8.GetString(G7.DecryptText(G7.K, "v27", G7.V27));
        var v2 = Encoding.UTF8.GetString(G7.DecryptText(G7.K, "v41", G7.V41));
        if (h1 != v1 || h2 != v2) Drop();
        return null;
    }

    static string PathOf(string a, string b)
    {
        var sb = new StringBuilder();
        sb.Append('/');
        sb.Append(a);
        sb.Append('/');
        sb.Append(b);
        return sb.ToString();
    }

    static string QDefault() => Encoding.UTF8.GetString(G7.DecryptText(G7.K, "qua", G7.TQUA));

    static string P_Info() => PathOf("api", "sign") + "/sec-sign/appinfo_v2";
    static string P_Sign() => PathOf("api", "sign") + "/sec-sign";

    static bool TryParseJson(string text, out string cmd, out string uin, out string body, out string qua)
    {
        cmd = null;
        uin = null;
        body = null;
        qua = null;
        if (string.IsNullOrWhiteSpace(text)) return true;
        try
        {
            using var doc = JsonDocument.Parse(text);
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object) return true;

            if (root.TryGetProperty("cmd", out var pc)) cmd = pc.ToString();
            else if (root.TryGetProperty("command", out var pc2)) cmd = pc2.ToString();

            if (root.TryGetProperty("uin", out var pu)) uin = pu.ToString();

            if (root.TryGetProperty("body", out var p1)) body = p1.ToString();
            else if (root.TryGetProperty("src", out var p2)) body = p2.ToString();

            if (root.TryGetProperty("qua", out var p3)) qua = p3.ToString();
            else if (root.TryGetProperty("ver", out var p4)) qua = p4.ToString();

            return true;
        }
        catch { return false; }
    }

    static string Q(HttpRequest req, params string[] keys)
    {
        foreach (var k in keys)
        {
            var v = req.Query[k];
            if (!string.IsNullOrEmpty(v)) return v;
        }
        return null;
    }

    static IResult JsonOut(HttpContext ctx, string json, int status = 200)
    {
        ctx.Response.StatusCode = status;
        return Results.Text(json, "application/json; charset=utf-8", Encoding.UTF8);
    }

    static void Boot()
    {
        VerifyBlobs();
        G7.Blob27();
        G7.Blob41();
        if (Guard(true)) Drop();
    }

    static async Task Main(string[] args)
    {
        if (args.Length > 0 && args[0] == "selftest")
        {
#if SELF
            Self.Run(args);
#else
            Console.Error.WriteLine("self-test not compiled");
#endif
            return;
        }
        await Run(args);
    }

    const string Art = """
                 _   _ _____ ___   ___        ____                 ____  _             ____
                | \ | |_   _/ _ \ / _ \      |  _ \ _   _ _ __ ___/ ___|(_) __ _ _ __ / ___|  ___ _ ____   _____ _ __
                |  \| | | || | | | | | |_____| |_) | | | | '__/ _ \___ \| |/ _` | '_ \\___ \ / _ \ '__\ \ / / _ \ '__|
                | |\  | | || |_| | |_| |_____|  __/| |_| | | |  __/___) | | (_| | | | |___) |  __/ |   \ V /  __/ |
                |_| \_| |_| \__\_\\__\_\     |_|    \__,_|_|  \___|____/|_|\__, |_| |_|____/ \___|_|    \_/ \___|_|
                                                                           |___/
                """;

    static void Banner()
    {
        try
        {
            Console.ForegroundColor = ConsoleColor.Magenta;
            if (Console.BufferWidth >= 45) Console.WriteLine(Art);
            else Console.WriteLine("NTQQ-PureSignServer");
            Console.ResetColor();
            Console.WriteLine("Version 1.0.0 By Bocchi");
            Console.WriteLine("NTQQ Version Linux QQ 3.2.34-53644");
        }
        catch
        {
            Console.WriteLine("NTQQ-PureSignServer");
            Console.WriteLine("Version 1.0.0 By Bocchi");
            Console.WriteLine("NTQQ Version Linux QQ 3.2.34-53644");
        }
    }

    static async Task Run(string[] args)
    {
        try { Console.OutputEncoding = Encoding.UTF8; }
        catch { }

        Banner();
        Console.WriteLine();

        var cfg = LoadOrCreateConfig();

        string bind = cfg.Server?.Host ?? "127.0.0.1";
        int port = cfg.Server?.Port ?? 8080;
        if (args.Length > 0 && int.TryParse(args[0], out int p)) port = p;
        if (args.Length > 1 && !string.IsNullOrEmpty(args[1])) bind = args[1];

        Boot();

        var builder = WebApplication.CreateBuilder(args);
        builder.Logging.ClearProviders();
        builder.WebHost.UseUrls("http://" + bind + ":" + port + "/");

        var app = builder.Build();

        if ((Gate ^ Gate) != 0) Drop();

        string pSign = P_Sign();
        string pInfo = P_Info();

        var whitelistSet = new HashSet<string>(cfg.Whitelist?.CmdWhitelist ?? new List<string>(), StringComparer.Ordinal);
        var tokenSet = new HashSet<string>(cfg.Auth?.Tokens ?? new List<string>(), StringComparer.Ordinal);

        app.Use(async (ctx, next) =>
        {
            ctx.Response.Headers["Access-Control-Allow-Origin"] = "*";
            if (ctx.Request.Method == "OPTIONS")
            {
                ctx.Response.StatusCode = 200;
                return;
            }
            string rp = ctx.Request.Path.Value ?? "/";
            if (rp.Length > 1 && rp.EndsWith("/", StringComparison.Ordinal)) rp = rp.TrimEnd('/');
            if (string.Equals(rp, pSign, StringComparison.OrdinalIgnoreCase)
                && ctx.Request.Method != "GET" && ctx.Request.Method != "POST")
            {
                ctx.Response.StatusCode = 404;
                return;
            }
            await next();
        });

        app.MapGet(pInfo, async (HttpContext ctx) =>
        {
            if (Guard(false)) { Drop(); return Results.Empty; }
            string info = "{\"code\":0,\"message\":\"ok\",\"value\":" + Encoding.UTF8.GetString(G7.AppInfoJson()) + "}";
            return JsonOut(ctx, info);
        });

        app.MapGet(pSign, (HttpContext ctx) =>
        {
            if (Guard(false)) { Drop(); return Results.Empty; }
            string cmd = Q(ctx.Request, "cmd", "command");
            string uin = Q(ctx.Request, "uin");
            string body = Q(ctx.Request, "body", "src");
            string qua = Q(ctx.Request, "qua", "ver");
            return DoSign(ctx, cfg, whitelistSet, tokenSet, cmd, uin, body, qua);
        });

        app.MapPost(pSign, async (HttpContext ctx) =>
        {
            if (Guard(false)) { Drop(); return Results.Empty; }
            string raw;
            using (var reader = new StreamReader(ctx.Request.Body, Encoding.UTF8))
                raw = await reader.ReadToEndAsync();
            if (!TryParseJson(raw, out string cmd, out string uin, out string body, out string qua))
            {
                LogWarn($"Request body is not valid JSON from {ctx.Connection.RemoteIpAddress}");
                return JsonOut(ctx, "{\"code\":-1,\"message\":\"bad json body\"}", 400);
            }
            if (string.IsNullOrEmpty(cmd)) cmd = Q(ctx.Request, "cmd", "command");
            if (string.IsNullOrEmpty(uin)) uin = Q(ctx.Request, "uin");
            if (string.IsNullOrEmpty(body)) body = Q(ctx.Request, "body", "src");
            if (string.IsNullOrEmpty(qua)) qua = Q(ctx.Request, "qua", "ver");
            return DoSign(ctx, cfg, whitelistSet, tokenSet, cmd, uin, body, qua);
        });

        app.MapGet("/sign", (HttpContext ctx) =>
        {
            if (Guard(false)) { Drop(); return Results.Empty; }
            string cmd = Q(ctx.Request, "cmd", "command");
            string uin = Q(ctx.Request, "uin");
            string body = Q(ctx.Request, "body", "src");
            string qua = Q(ctx.Request, "qua", "ver");
            return DoSign(ctx, cfg, whitelistSet, tokenSet, cmd, uin, body, qua);
        });

        app.MapPost("/sign", async (HttpContext ctx) =>
        {
            if (Guard(false)) { Drop(); return Results.Empty; }
            string raw;
            using (var reader = new StreamReader(ctx.Request.Body, Encoding.UTF8))
                raw = await reader.ReadToEndAsync();
            if (!TryParseJson(raw, out string cmd, out string uin, out string body, out string qua))
            {
                LogWarn($"Request body is not valid JSON from {ctx.Connection.RemoteIpAddress}");
                return JsonOut(ctx, "{\"code\":-1,\"message\":\"bad json body\"}", 400);
            }
            if (string.IsNullOrEmpty(cmd)) cmd = Q(ctx.Request, "cmd", "command");
            if (string.IsNullOrEmpty(uin)) uin = Q(ctx.Request, "uin");
            if (string.IsNullOrEmpty(body)) body = Q(ctx.Request, "body", "src");
            if (string.IsNullOrEmpty(qua)) qua = Q(ctx.Request, "qua", "ver");
            return DoSign(ctx, cfg, whitelistSet, tokenSet, cmd, uin, body, qua);
        });

        app.Lifetime.ApplicationStarted.Register(() =>
        {
            LogInfo($"NTQQ-PureSignServer started, listening on http://{bind}:{port}/");
            Console.WriteLine($"Please use Lagrange.Milky or Yogurt or EulerOnebot to request the sign server at http://{bind}:{port}/api/");
        });

        await app.RunAsync();
    }

    static bool CheckWildcard(HashSet<string> set, string cmd)
    {
        if (set == null) return false;
        foreach (var rule in set)
        {
            if (rule.EndsWith("*", StringComparison.Ordinal) && cmd.StartsWith(rule.Substring(0, rule.Length - 1), StringComparison.Ordinal))
                return true;
        }
        return false;
    }

    static string Abbr(string s, int maxLen = 24)
    {
        if (string.IsNullOrEmpty(s)) return "\"\"";
        return s.Length > maxLen ? s.Substring(0, maxLen) + "..." : s;
    }

    static IResult DoSign(HttpContext ctx, AppConfig cfg, HashSet<string> whitelistSet, HashSet<string> tokenSet, string cmd, string uin, string body, string qua)
    {
        if (cfg.Auth != null && cfg.Auth.EnableTokenAuth)
        {
            string authHeader = ctx.Request.Headers["Authorization"].ToString();
            string token = null;
            if (!string.IsNullOrEmpty(authHeader) && authHeader.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase))
            {
                token = authHeader.Substring(7).Trim();
            }
            if (string.IsNullOrEmpty(token))
            {
                token = Q(ctx.Request, "token", "access_token");
            }
            if (string.IsNullOrEmpty(token))
            {
                LogWarn($"Missing Authorization token from {ctx.Connection.RemoteIpAddress}");
                return JsonOut(ctx, "{\"code\":-1,\"message\":\"Missing Authorization: Bearer <access-token>\"}", 401);
            }
            if (tokenSet == null || !tokenSet.Contains(token))
            {
                LogWarn($"Invalid access-token from {ctx.Connection.RemoteIpAddress}");
                return JsonOut(ctx, "{\"code\":-1,\"message\":\"Invalid access-token\"}", 403);
            }
        }

        if (cfg.Whitelist != null && cfg.Whitelist.EnableCmdWhitelist)
        {
            if (string.IsNullOrWhiteSpace(cmd))
            {
                LogWarn($"Command parameter is empty from {ctx.Connection.RemoteIpAddress}");
                return JsonOut(ctx, "{\"code\":-1,\"message\":\"Command parameter cannot be empty\"}", 400);
            }
            cmd = cmd.Trim();
            if (whitelistSet == null || (!whitelistSet.Contains(cmd) && !CheckWildcard(whitelistSet, cmd)))
            {
                LogWarn($"Command is not in whitelist: {cmd} from {ctx.Connection.RemoteIpAddress}");
                return JsonOut(ctx, "{\"code\":-1,\"message\":\"Command is not in whitelist: " + cmd + "\"}", 403);
            }
        }

        if (body == null) body = "";
        body = body.Trim();
        if (body.Length > 0 && !System.Text.RegularExpressions.Regex.IsMatch(body, "^[0-9a-fA-F]*$"))
        {
            LogWarn($"Body is not valid hex from {ctx.Connection.RemoteIpAddress}");
            return JsonOut(ctx, "{\"code\":-1,\"message\":\"Body must be hex\"}", 400);
        }
        if (string.IsNullOrEmpty(qua)) qua = QDefault();
        try
        {
            uint us = (uint)((DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() % 1000) * 1000);
            var sw = Stopwatch.StartNew();
            var r = G7.ComputeSign(G7.HexToBytes(body), qua, us);
            sw.Stop();
            if (string.IsNullOrEmpty(uin)) uin = "-";
            LogInfo($"Sign completed uin={uin} body={body.Length / 2}B us={us} sec_sign={Abbr(r.sec_sign, 24)} sec_token={Abbr(r.sec_token, 16)} sec_extra={Abbr(r.sec_extra, 24)} ({sw.ElapsedMilliseconds} ms)");
            string json = "{\"code\":0,\"message\":null,\"value\":{\"sec_sign\":\"" + r.sec_sign +
                "\",\"sec_token\":\"" + r.sec_token + "\",\"sec_extra\":\"" + r.sec_extra + "\"}}";
            return JsonOut(ctx, json);
        }
        catch (Exception ex)
        {
            LogError($"Sign computation failed: {ex.Message}");
            return JsonOut(ctx, "{\"code\":-1,\"message\":" + JsonSerializer.Serialize(ex.Message) + "}", 500);
        }
    }
}

internal static class ParentUtilities
{
    [StructLayout(LayoutKind.Sequential)]
    struct Pbi
    {
        public IntPtr Reserved1;
        public IntPtr PebBaseAddress;
        public IntPtr Reserved2a;
        public IntPtr Reserved2b;
        public IntPtr UniqueProcessId;
        public IntPtr InheritedFromUniqueProcessId;
    }

    [DllImport("ntdll.dll")]
    static extern int NtQueryInformationProcess(IntPtr processHandle, int processInformationClass, ref Pbi processInformation, int processInformationLength, out int returnLength);

    public static string ParentOf(int pid)
    {
        if (!OperatingSystem.IsWindows()) return null;
        try
        {
            var me = Process.GetCurrentProcess();
            var pbi = new Pbi();
            int rl;
            int st = NtQueryInformationProcess(me.Handle, 0, ref pbi, Marshal.SizeOf<Pbi>(), out rl);
            if (st != 0) return null;
            int ppid = pbi.InheritedFromUniqueProcessId.ToInt32();
            if (ppid <= 0) return null;
            var par = Process.GetProcessById(ppid);
            return par.ProcessName;
        }
        catch { return null; }
    }
}

#if SELF
internal static class Self
{
    static readonly byte[] R16 = new byte[16];

    internal static void Run(string[] args)
    {
        string file = args.Length > 1 ? args[1] : null;
        if (file == null)
        {
            Console.WriteLine("usage: svc selftest <jsonl>");
            return;
        }
        int ok = 0, bad = 0;
        var fails = new List<string>();
        foreach (var line in System.IO.File.ReadLines(file))
        {
            if (string.IsNullOrWhiteSpace(line)) continue;
            using var doc = JsonDocument.Parse(line);
            var body = doc.RootElement.GetProperty("body").GetString();
            uint us = doc.RootElement.GetProperty("us").GetUInt32();
            var expSign = doc.RootElement.GetProperty("sec_sign").GetString();
            var expExtra = doc.RootElement.GetProperty("sec_extra").GetString();
            var r = G7.ComputeSign(G7.HexToBytes(body), Encoding.UTF8.GetString(G7.DecryptText(G7.K, "qua", G7.TQUA)), us, R16);
            if (r.sec_sign == expSign && r.sec_extra == expExtra) ok++;
            else { bad++; fails.Add("body=" + body.Substring(0, Math.Min(20, body.Length)) + " us=" + us); }
        }
        Console.WriteLine("OK=" + ok + " BAD=" + bad);
        foreach (var f in fails) Console.WriteLine("FAIL " + f);
    }
}
#endif
